import json, sys

def walk(obj, path="$"):
    if isinstance(obj, dict):
        for k, v in obj.items():
            p = f"{path}.{k}"
            if isinstance(v, (dict, list)): yield p, type(v).__name__; yield from walk(v, p)
            else: yield p, repr(v)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            p = f"{path}[{i}]"
            if isinstance(v, (dict, list)): yield p, type(v).__name__; yield from walk(v, p)
            else: yield p, repr(v)

data = json.load(open("{{input_file}}"))
print(json.dumps(data, indent=2, ensure_ascii=False))
print("\n--- paths ---")
for p, v in walk(data): print(f"{p:50s} {v}")
